// ikj multiplication. (mxk) * (kxn) = (mxn)
// this is good for small to medium size matrices
void matrix_xply(Matrixf* restrict out, const Matrixf* restrict a, const Matrixf* restrict b)
{
    MAT_LIVE(out, "matrix_xply");
    WC_ASSERT(a->n == b->m, "incompatible matrix dimensions for multiplication");
    WC_ASSERT(out->m == a->m && out->n == b->n, "output matrix has wrong dimensions");

    u64 m = a->m; // rows of A
    u64 k = a->n; // cols of A = rows of B
    u64 n = b->n; // cols of B

    // Initialize output to zero
    memset(out->data, 0, sizeof(float) * m * n);

    // Block size for cache optimization
    const u64 BLOCK_SIZE = 16;

    // Blocked matrix multiplication (ikj order for cache efficiency)
    for (u64 i = 0; i < m; i += BLOCK_SIZE) {
        for (u64 k_outer = 0; k_outer < k; k_outer += BLOCK_SIZE) {
            for (u64 j = 0; j < n; j += BLOCK_SIZE) {
                // Block boundaries
                u64 i_max = (i + BLOCK_SIZE < m) ? i + BLOCK_SIZE : m;
                u64 k_max = (k_outer + BLOCK_SIZE < k) ? k_outer + BLOCK_SIZE : k;
                u64 j_max = (j + BLOCK_SIZE < n) ? j + BLOCK_SIZE : n;
                // Multiply this block
                for (u64 ii = i; ii < i_max; ii++) {
                    for (u64 kk = k_outer; kk < k_max; kk++) {

                        float a_val = a->data[IDX(a, ii, kk)];
                        for (u64 jj = j; jj < j_max; jj++) {
                            out->data[IDX(out, ii, jj)] += a_val * b->data[IDX(b, kk, jj)];
                        }
                    }
                }
            }
        }
    }
}


// this function transposes b for cache-friendly access
// takes more memory, good for large size matrices
void matrix_xply_2(Matrixf* restrict out, const Matrixf* restrict a, const Matrixf* restrict b)
{
    MAT_LIVE(out, "matrix_xply_2");
    WC_ASSERT(a->n == b->m, "incompatible matrix dimensions");
    WC_ASSERT(out->m == a->m && out->n == b->n, "output matrix has wrong dimensions");

    u64 m = a->m;
    u64 k = a->n;
    u64 n = b->n;

    // Transpose B for cache-friendly access
    float   data[n * k]; // random vals
    Matrixf b_T = matrix_create_buf(n, k, data);
    matrix_T(&b_T, b); // transpose sets all vals

    memset(out->data, 0, sizeof(float) * m * n);

    const u64 BLOCK_SIZE = 16;

    // Now both A and B^T are accessed row-wise
    for (u64 i = 0; i < m; i += BLOCK_SIZE) {
        for (u64 j = 0; j < n; j += BLOCK_SIZE) {
            u64 i_max = (i + BLOCK_SIZE < m) ? i + BLOCK_SIZE : m;
            u64 j_max = (j + BLOCK_SIZE < n) ? j + BLOCK_SIZE : n;

            for (u64 ii = i; ii < i_max; ii++) {
                for (u64 jj = j; jj < j_max; jj++) {

                    float sum = 0;
                    // Dot product of A[ii] and B_T[jj] (both row-wise)
                    for (u64 kk = 0; kk < k; kk++) {
                        sum += a->data[IDX(a, ii, kk)] *
                               // b_T->data[IDX(b_T, jj, kk)];
                               b_T.data[IDX(&b_T, jj, kk)];
                    }
                    out->data[IDX(out, ii, jj)] = sum;
                }
            }
        }
    }
}

/*
Doolittle algorithm computes U's i-th row, then L's i-th column, alternating.
For each element, you subtract the dot product of already-computed L and U values.
*/
void matrix_LU_Decomp(Matrixf* restrict L, Matrixf* restrict U, const Matrixf* restrict mat)
{
    MAT_LIVE(L, "matrix_LU_Decomp");
    MAT_LIVE(U, "matrix_LU_Decomp");
    WC_ASSERT(mat->n == mat->m, "mat is not a square matrix");
    WC_ASSERT(L->n == mat->n && L->m == mat->m, "L dimensions don't match");
    WC_ASSERT(U->n == mat->n && U->m == mat->m, "U dimensions don't match");

    const u64 n = mat->n;

    // 0 init matrices
    memset(L->data, 0, sizeof(float) * n * n);
    memset(U->data, 0, sizeof(float) * n * n);
    // L main diagonal is 1
    for (u64 i = 0; i < n; i++) {
        L->data[IDX(L, i, i)] = 1;
    }


    // Build U and L row by row
    for (u64 i = 0; i < n; i++) {
        // Upper triangular matrix U (row i, columns from i to n-1)
        for (u64 k = i; k < n; k++) {
            float sum = 0;
            for (u64 j = 0; j < i; j++) {
                sum += L->data[IDX(L, i, j)] * U->data[IDX(U, j, k)];
            }
            U->data[IDX(U, i, k)] = MATRIX_AT(mat, i, k) - sum;
        }

        // Lower triangular matrix L (column i, rows from i+1 to n-1)
        for (u64 k = i + 1; k < n; k++) {
            float sum = 0;
            for (u64 j = 0; j < i; j++) {
                sum += L->data[IDX(L, k, j)] * U->data[IDX(U, j, i)];
            }

            // Check for zero diagonal in U (would cause division by zero)
            if (U->data[IDX(U, i, i)] == 0) {
                WC_ASSERT(0, "Matrix is singular - LU decomposition failed");
            }

            L->data[IDX(L, k, i)] = (MATRIX_AT(mat, k, i) - sum) / U->data[IDX(U, i, i)];
        }
    }
}

/*
    det of triangular mat is product of main diagonal
    so det of a mat that is decomposed with LU method becomes
    product of elements on the diagonal of L and U
    det(A) = det(L) * det(U)
    
    Since L has 1s on diagonal: det(L) = 1
    So: det(A) = det(U) = product of U's diagonal elements
    
    LU Decomposition is when we make 2 triangular matrices from one,
    which when multiplied give original matrix: A = L * U
*/
float matrix_det(const Matrixf* mat)
{
    WC_ASSERT(mat->m == mat->n, "only square matrices have determinant");


    u64 n = mat->n;

    float   Ldata[n * n]; // random vals
    float   Udata[n * n];
    Matrixf L = matrix_create_buf(n, n, Ldata);
    Matrixf U = matrix_create_buf(n, n, Udata);

    // Perform LU decomposition
    matrix_LU_Decomp(&L, &U, mat); // L and U set to zero

    // Calculate determinant as product of U's diagonal
    float det = 1;
    for (u64 i = 0; i < n; i++) {
        det *= U.data[IDX(&U, i, i)];
    }

    return det;
}


/*
    In-place Gauss-Jordan with partial pivoting.
    For each column k: pick the row with the largest |a[i][k]| at or below k,
    swap it up, scale the pivot row so the pivot becomes 1 (storing 1/pivot in
    its place), and eliminate column k from every other row. Each row swap is
    recorded; undoing them as COLUMN swaps in reverse order leaves the inverse.
*/
bool matrix_inv(Matrixf* restrict out, const Matrixf* restrict mat)
{
    MAT_LIVE(out, "matrix_inv");
    WC_ASSERT(mat->m == mat->n, "only square matrices have an inverse");
    WC_ASSERT(out->m == mat->m && out->n == mat->n, "out dimensions don't match");

    const u64 n = mat->n;
    float*    a = out->data;
    memcpy(a, mat->data, sizeof(float) * n * n);

    u64 piv[n]; // row swapped into position k

    for (u64 k = 0; k < n; k++) {
        u64   p    = k;
        float best = a[(k * n) + k] < 0 ? -a[(k * n) + k] : a[(k * n) + k];
        for (u64 i = k + 1; i < n; i++) {
            float v = a[(i * n) + k] < 0 ? -a[(i * n) + k] : a[(i * n) + k];
            if (v > best) {
                best = v;
                p    = i;
            }
        }
        if (best == 0.0F) {
            return false; // singular
        }

        piv[k] = p;
        if (p != k) {
            for (u64 j = 0; j < n; j++) {
                float t          = a[(k * n) + j];
                a[(k * n) + j]   = a[(p * n) + j];
                a[(p * n) + j]   = t;
            }
        }

        float inv_p    = 1.0F / a[(k * n) + k];
        a[(k * n) + k] = 1.0F;
        for (u64 j = 0; j < n; j++) {
            a[(k * n) + j] *= inv_p;
        }

        for (u64 i = 0; i < n; i++) {
            if (i == k) {
                continue;
            }
            float f        = a[(i * n) + k];
            a[(i * n) + k] = 0.0F;
            if (f != 0.0F) {
                for (u64 j = 0; j < n; j++) {
                    a[(i * n) + j] -= f * a[(k * n) + j];
                }
            }
        }
    }

    // undo the row swaps as column swaps, last first
    for (u64 k = n; k-- > 0;) {
        if (piv[k] != k) {
            for (u64 i = 0; i < n; i++) {
                float t                = a[(i * n) + k];
                a[(i * n) + k]         = a[(i * n) + piv[k]];
                a[(i * n) + piv[k]]    = t;
            }
        }
    }
    return true;
}


void matrix_T(Matrixf* restrict out, const Matrixf* restrict mat)
{
    MAT_LIVE(out, "matrix_T");
    WC_ASSERT(mat->m == out->n && mat->n == out->m, "incompatible matrix dimensions");

    // Block size for cache optimization (tune with -DWC_MAT_BLOCK=n)
    const u64 BLOCK_SIZE = WC_MAT_BLOCK;

    // Blocked transpose: process matrix in BLOCK_SIZE x BLOCK_SIZE tiles
    for (u64 i = 0; i < mat->m; i += BLOCK_SIZE) {
        for (u64 j = 0; j < mat->n; j += BLOCK_SIZE) {

            // Calculate block boundaries
            u64 i_max = (i + BLOCK_SIZE < mat->m) ? i + BLOCK_SIZE : mat->m;
            u64 j_max = (j + BLOCK_SIZE < mat->n) ? j + BLOCK_SIZE : mat->n;

            // Transpose the block
            for (u64 ii = i; ii < i_max; ii++) {
                for (u64 jj = j; jj < j_max; jj++) {
                    // mat[ii][jj] -> out[jj][ii]
                    out->data[IDX(out, jj, ii)] = mat->data[IDX(mat, ii, jj)];
                }
            }
        }
    }
}

void matrix_scale(Matrixf* restrict mat, float val)
{
    MAT_LIVE(mat, "matrix_scale");
    u64 total = MATRIX_TOTAL(mat);
    for (u64 i = 0; i < total; i++) {
        mat->data[i] *= val;
    }
}


void matrix_div(Matrixf* restrict mat, float val)
{
    MAT_LIVE(mat, "matrix_div");
    WC_ASSERT(val != 0, "division by zero!");

    u64 total = MATRIX_TOTAL(mat);
    for (u64 i = 0; i < total; i++) {
        mat->data[i] /= val;
    }
}

Matrixf matrix_copy(const wc_allocator* a, const Matrixf* src)
{
    MAT_LIVE(src, "matrix_copy");
    return matrix_create_arr(a, src->m, src->n, src->data);
}

void matrix_move(Matrixf* dest, Matrixf* src)
{
    if (dest == src) {
        return;
    }
    memcpy(dest, src, sizeof(Matrixf));
    memset(src, 0, sizeof(Matrixf));
}

void matrix_print(const Matrixf* mat)
{
    u64 total = mat->m * mat->n;

    // Single linear loop O(n)
    for (u64 i = 0; i < total; i++) {
        // Print row separator
        if (i % mat->n == 0) { // divide by columns to detect new row
            if (i > 0) {
                putchar('|');
            } // Close previous row
            putchar('\n');
            putchar('|');
            putchar(' ');
        }

        // Print element
        printf("%f ", mat->data[i]);
    }

    // Close last row
    putchar('|');
    putchar('\n');
}

