#include <stdio.h>
#include <string.h>


#define DS(q)          ((u64)(q)->arr.data_size)
#define CAP(q)         ((q)->arr.capacity)
#define SLOT_PTR(q, s) ((q)->arr.data + ((s) * DS(q)))
#define DATA_ALIGN(q)  wc_align_for_size((q)->arr.data_size)

